CREATE TABLE wallet_account(user_id BIGINT NOT NULL,available_balance DECIMAL(18,2) NOT NULL DEFAULT 0,frozen_balance DECIMAL(18,2) NOT NULL DEFAULT 0,currency CHAR(3) CHARACTER SET ascii COLLATE ascii_bin NOT NULL DEFAULT 'CNY',status VARCHAR(16) CHARACTER SET ascii COLLATE ascii_bin NOT NULL DEFAULT 'ACTIVE',version BIGINT UNSIGNED NOT NULL DEFAULT 0,created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),PRIMARY KEY(user_id),CONSTRAINT chk_wallet_balances CHECK(available_balance>=0 AND frozen_balance>=0));
CREATE TABLE wallet_transaction(id BIGINT NOT NULL,request_id VARCHAR(128) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,user_id BIGINT NOT NULL,type VARCHAR(24) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,status VARCHAR(16) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,amount DECIMAL(18,2) NOT NULL,currency CHAR(3) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,reference_id VARCHAR(128) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,balance_before DECIMAL(18,2) NOT NULL,balance_after DECIMAL(18,2) NOT NULL,created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),completed_at DATETIME(6) NULL,PRIMARY KEY(id),UNIQUE KEY uk_wallet_transaction_request(request_id),INDEX idx_wallet_transaction_user_time(user_id,created_at),INDEX idx_wallet_transaction_reference(reference_id,type),CONSTRAINT fk_wallet_transaction_account FOREIGN KEY(user_id) REFERENCES wallet_account(user_id),CONSTRAINT chk_wallet_transaction_amount CHECK(amount>0));
CREATE TABLE wallet_outbox(id VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,aggregate_id VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,event_type VARCHAR(128) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,payload_json JSON NOT NULL,status VARCHAR(16) CHARACTER SET ascii COLLATE ascii_bin NOT NULL DEFAULT 'PENDING',retry_count INT UNSIGNED NOT NULL DEFAULT 0,next_retry_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),published_at DATETIME(6) NULL,PRIMARY KEY(id),INDEX idx_wallet_outbox_dispatch(status,next_retry_at));
CREATE TABLE wallet_inbox(event_id VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,event_type VARCHAR(128) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,processed_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),PRIMARY KEY(event_id));
